import pathlib,subprocess,json,itertools,statistics,hashlib
root=pathlib.Path('/home/ekhodzitsky/Projects/syom');out=root/'lab/release-audit/runs/candidate-0.9.0'
bins={'baseline':root/'target/cold-baseline-peer','candidate':root/'target/cold-candidate-peer'}
fixtures=['sine48.adts','lecture.m4a','he48e.adts','ps48.adts','mc51.adts','ld64m.loas'];rows=[]
for fixture in fixtures:
 for block,variant in enumerate(['baseline','candidate','candidate','baseline','candidate','baseline','baseline','candidate']):
  cmd=['taskset','-c','0',str(bins[variant]),'decode',str(root/'src/goldens'/fixture),'5','31']
  result=subprocess.run(cmd,capture_output=True,text=True,check=True)
  data=[json.loads(s) for s in result.stdout.splitlines() if s.startswith('{')]
  rows.append({'fixture':fixture,'block':block,'variant':variant,'command':cmd,'host':data[0],'measurement':data[-1]})
summaries=[]
for fixture in fixtures:
 med={variant:statistics.median([x for r in rows if r['fixture']==fixture and r['variant']==variant for x in r['measurement']['samples_ms']]) for variant in bins}
 summaries.append({'fixture':fixture,'pooled_median_ms':med,'candidate_over_baseline':med['candidate']/med['baseline']})
obj={'protocol':'CPU0 ABBA/BAAB,5warm+31reps;4blocks each engine/cell,124samples,full decode/free internal timer. No outlier removal. Busy shared host; no universal ranking.','baseline_revision':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'binary_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in bins.items()},'summaries':summaries}
s=json.dumps(obj,indent=2);(out/'decode-speed.json').write_text(s[:-2]+',\n  "rows": [\n'+',\n'.join('    '+json.dumps(x,separators=(',',':')) for x in rows)+'\n  ]\n}\n')
print(json.dumps(summaries,indent=2))
